"use client"

import * as React from "react"

import { cn } from "@/lib/utils"
import { Button } from "@/components/ui/button"
import { Field, FieldError, Textarea } from "@/components/ui/field"
import { Fraction } from "@/components/ui/fraction"
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group"

type Answers = Record<string, string | undefined>

type Question = {
  id: string
  question: React.ReactNode
  /** The choices. Leave it out for a free-text question, which is always optional. */
  options?: string[]
  /** Free-text questions only: the label over the line. */
  label?: string
  /** Free-text questions only. */
  placeholder?: string
}

type QuestionnaireProps = Omit<React.ComponentProps<"form">, "onSubmit" | "children"> & {
  /**
   * sentence (the default): one question at a time; at the end, your answers written into one sentence.
   * interview: every question asked stays above the next, small, with your answer beside it, like the
   * printed interview's Q and A; press an answer to go back to it. definition: at the end you are
   * defined, as the dictionary sets an entry: the headword reversed out of ink, then the sentence.
   */
  variant?: "sentence" | "interview" | "definition"
  questions: Question[]
  /** Writes the answers into one sentence. Only what was answered is in `answers`. */
  sentence: (answers: Answers) => string
  onComplete?: (answers: Answers) => void
  /** The last question's action. */
  submitLabel?: string
  /** Said when a choice is needed to go on. */
  error?: string
  /** Definition only: the headword and its part of speech, from the answers. */
  entry?: (answers: Answers) => { word: string; kind: string }
  /** Answers to start from, to resume a questionnaire. */
  defaultAnswers?: Answers
  /** The question to start at, to resume one (its length is the end). */
  defaultStep?: number
}

/**
 * Questions one at a time, set large. In an interview the asked ones stay above as Q and A; in a
 * definition the end is a dictionary entry. The count rolls, the hairline fills, and each
 * question turns in from the side you're heading. At the end your answers are written
 * into one sentence in italic, word by word.
 */
function Questionnaire({
  variant = "sentence",
  questions,
  sentence,
  onComplete,
  submitLabel = "Send answers",
  error = "Choose one to go on, or skip this question.",
  entry,
  defaultAnswers,
  defaultStep = 0,
  className,
  ...props
}: QuestionnaireProps) {
  const base = React.useId()
  const total = questions.length
  const [at, setAt] = React.useState(() => Math.min(Math.max(0, defaultStep), total))
  const [dir, setDir] = React.useState<1 | -1>(1)
  const [turned, setTurned] = React.useState(false)
  const [answers, setAnswers] = React.useState<Answers>(() => defaultAnswers ?? {})
  const [missing, setMissing] = React.useState(false)
  const step = React.useRef<HTMLDivElement>(null)
  const again = React.useRef<HTMLButtonElement>(null)
  const moved = React.useRef(false)

  const done = at >= total
  const q = questions[at]
  const clean = (): Answers => Object.fromEntries(Object.entries(answers).filter(([, v]) => v?.trim()))
  const said = done && variant === "definition" && entry ? entry(clean()) : null

  // The count rolls the way you're heading (the fraction turns its own figures over).
  const n = Math.min(at + 1, total)

  // Focus goes to each new question (not on first load).
  React.useEffect(() => {
    if (!moved.current) return
    if (done) again.current?.focus({ preventScroll: true })
    else (step.current?.querySelector<HTMLElement>("input:checked") ?? step.current?.querySelector<HTMLElement>("input, textarea"))?.focus({ preventScroll: true })
  }, [at, done])

  function go(to: number, heading: 1 | -1) {
    moved.current = true
    setDir(heading)
    setTurned(true)
    setMissing(false)
    setAt(to)
  }

  function set(id: string, value: string) {
    setMissing(false)
    setAnswers((a) => ({ ...a, [id]: value }))
  }

  return (
    <form
      data-slot="questionnaire"
      noValidate
      data-variant={variant}
      className={cn("db-quest", className)}
      onSubmit={(e) => {
        e.preventDefault()
        if (done) return
        if (q.options && !answers[q.id]) return setMissing(true)
        if (at === total - 1) onComplete?.(clean())
        go(at + 1, 1)
      }}
      {...props}
    >
      <div data-slot="questionnaire-head" className="db-quest-head">
        <Fraction aria-hidden="true" count={n} total={total} />
        <progress max={total} value={n} aria-label={done ? `All ${total} answered` : `Question ${n} of ${total}`} />
      </div>

      {variant === "interview" && at > 0 ? (
        <ol data-slot="questionnaire-log" className="db-quest-log">
          {questions.slice(0, at).map((p, i) => {
            const a = answers[p.id]?.trim()
            return (
              <li key={p.id}>
                <p id={`${base}-log-${p.id}`} className="db-quest-log-q">
                  <span className="db-quest-hang" aria-hidden="true">Q</span>
                  {p.question}
                </p>
                <p className="db-quest-log-a">
                  <span className="db-quest-hang" aria-hidden="true">A</span>
                  <button type="button" aria-describedby={`${base}-log-${p.id}`} onClick={() => go(i, -1)}>
                    {a ? <span className="db-yours">{a}</span> : "Skipped"}
                    <span className="db-sr">, change</span>
                  </button>
                </p>
              </li>
            )
          })}
        </ol>
      ) : null}

      {q ? (
        <div
          key={at}
          ref={step}
          data-slot="questionnaire-step"
          data-arriving={turned ? "" : undefined}
          className="db-quest-step"
          style={{ "--from": dir * 3 } as React.CSSProperties}
        >
          <p id={`${base}-${q.id}`} data-slot="questionnaire-question" className="db-quest-q">
            {q.question}
          </p>
          {q.options ? (
            <RadioGroup aria-labelledby={`${base}-${q.id}`} value={answers[q.id] ?? ""} onValueChange={(v) => set(q.id, v)}>
              {q.options.map((o) => (
                <RadioGroupItem key={o} value={o}>
                  {o}
                </RadioGroupItem>
              ))}
            </RadioGroup>
          ) : (
            <Field label={q.label ?? "Optional"}>
              <Textarea
                rows={2}
                maxLength={200}
                placeholder={q.placeholder}
                aria-describedby={`${base}-${q.id}`}
                value={answers[q.id] ?? ""}
                onChange={(e) => set(q.id, e.target.value)}
              />
            </Field>
          )}
        </div>
      ) : null}

      {/* Always mounted, so the sentence is announced when it arrives. */}
      <div data-slot="questionnaire-end" data-done={done ? "" : undefined} className="db-quest-step">
        <div data-slot="questionnaire-said" className="db-quest-said" aria-live="polite">
          {said ? (
            <p data-slot="questionnaire-entry" className="db-quest-entry">
              <span className="db-quest-word db-yours">{said.word}</span>
              <span className="db-quest-kind">{said.kind}</span>
            </p>
          ) : null}
          {done ? (
            <p data-slot="questionnaire-sentence" className="db-quest-sentence">
              {sentence(clean())
                .split(" ")
                .map((w, i) => (
                  <React.Fragment key={i}>
                    {i ? " " : null}
                    <span className="db-yours" style={{ "--i": i } as React.CSSProperties}>
                      {w}
                    </span>
                  </React.Fragment>
                ))}
            </p>
          ) : null}
        </div>
        {done ? (
          <Button
            ref={again}
            variant="quiet"
            onClick={() => {
              setAnswers({})
              go(0, -1)
            }}
          >
            Start again
          </Button>
        ) : null}
      </div>

      {missing ? <FieldError role="alert">{error}</FieldError> : null}

      {done ? null : (
        <div data-slot="questionnaire-actions" className="db-quest-actions">
          {at > 0 ? (
            <Button variant="quiet" onClick={() => go(at - 1, -1)}>
              Back
            </Button>
          ) : null}
          {at < total - 1 ? (
            <Button
              variant="quiet"
              onClick={() => {
                setAnswers((a) => ({ ...a, [q.id]: undefined }))
                go(at + 1, 1)
              }}
            >
              Skip
            </Button>
          ) : null}
          <Button variant="statement" type="submit">
            {at === total - 1 ? submitLabel : "Next"}
          </Button>
        </div>
      )}
    </form>
  )
}

export { Questionnaire, type QuestionnaireProps, type Question, type Answers }

@layer components {
  /* ── db-quest ── questions one at a time; your answers are written into one sentence */
  .db-quest { display: grid; gap: var(--db-space-6); }
  .db-quest-head { display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; column-gap: var(--db-space-5); }
  .db-quest-head .db-fraction { font-size: var(--db-mf); }
  .db-quest-head .db-fraction > .db-yours { display: inline-block; }
  .db-quest-head progress { -webkit-appearance: none; appearance: none; width: 100%; height: var(--db-stroke); border: 0; background: var(--db-rule); color: var(--db-ink); }
  .db-quest-head progress::-webkit-progress-bar { background: transparent; } /* the element draws the track, or a translucent rule would be laid on itself */
  .db-quest-head progress::-webkit-progress-value { background: var(--db-ink); transition: inline-size var(--db-andante) var(--db-breath); }
  .db-quest-head progress::-moz-progress-bar { background: var(--db-ink); }
  .db-quest-step { display: grid; gap: var(--db-space-5); min-width: 0; }
  .db-quest-step[data-arriving] { animation: db-quest-turn var(--db-andante) var(--db-exhale) backwards; }
  /* The sentence's home stays in the tree so its live region is heard; until the end it takes no room. */
  .db-quest-step[data-slot="questionnaire-end"]:not([data-done]) { position: absolute; }
  .db-quest-step > .db-btn { justify-self: start; }
  .db-quest-q { font-size: var(--db-f); line-height: var(--db-f-lh); letter-spacing: var(--db-f-tr); font-weight: 300; color: var(--db-ink); text-wrap: balance; }
  .db-quest-sentence { font-size: var(--db-mf); line-height: 1.35; letter-spacing: var(--db-mf-tr); font-weight: 300; color: var(--db-ink); text-wrap: pretty; }
  .db-quest-sentence > .db-yours { display: inline-block; animation: db-arrive var(--db-andante) var(--db-exhale) backwards; animation-delay: calc(5 * var(--db-arpeggio) + var(--i, 0) * var(--db-arpeggio)); }
  .db-quest-actions { display: flex; flex-wrap: wrap; align-items: center; gap: var(--db-space-5) var(--db-space-6); }
  .db-quest-actions > [data-variant="statement"] { margin-inline-start: auto; }
  /* interview: the printed interview's Q and A. What's been asked stays, small, above the next question;
     the letters hang in the margin, and step in where there's no margin to hang them in. */
  .db-quest-log { display: grid; gap: var(--db-space-4); margin: 0; padding: 0; list-style: none; }
  .db-quest-log > li { display: grid; gap: var(--db-space-1); animation: db-arrive var(--db-andante) var(--db-exhale) backwards; }
  .db-quest-log p { display: grid; grid-template-columns: var(--db-space-5) minmax(0, 1fr); align-items: baseline; margin: 0; }
  .db-quest-hang { font-size: var(--db-pp); line-height: 1; font-weight: 600; letter-spacing: 0.04em; color: var(--db-pencil); }
  .db-quest-log-q { font-size: var(--db-p); line-height: var(--db-p-lh); color: var(--db-graphite); }
  .db-quest-log-a { font-size: var(--db-mp); line-height: var(--db-mp-lh); }
  .db-quest-log-a > button { justify-self: start; padding: 0; border: 0; background: none; font: inherit; color: var(--db-pencil); text-align: start; cursor: pointer; text-decoration: underline var(--db-hairline) transparent; text-underline-offset: 0.25em; transition: text-decoration-color var(--db-allegro) var(--db-breath); }
  .db-quest-log-a > button > .db-yours { color: var(--db-ink); }
  .db-quest-log-a > button:hover, .db-quest[data-force~="hover"] .db-quest-log > li:last-child .db-quest-log-a > button { text-decoration-color: var(--db-rule-strong); }
  .db-quest-log-a > button:active { text-decoration-color: var(--db-ink); }
  @media (min-width: 860px) { .db-quest-log p { margin-inline-start: calc(-1 * var(--db-space-5)); } }

  /* definition: after "the uncreative", the end set as a dictionary entry. The headword is yours, in italic,
     reversed out of an ink block that draws across behind it; the part of speech under it, then the sense. */
  .db-quest-said { display: grid; gap: var(--db-space-4); }
  .db-quest-entry { display: grid; justify-items: start; gap: var(--db-space-2); margin: 0; }
  .db-quest-word { position: relative; isolation: isolate; padding: 0.02em 0.14em 0.1em 0.06em; font-size: var(--db-ff); line-height: 1; letter-spacing: var(--db-ff-tr); color: var(--db-paper); overflow-wrap: anywhere; }
  .db-quest-word::before { content: ""; position: absolute; inset: 0; z-index: -1; background: var(--db-ink); transform-origin: 0 50%; animation: db-draw-x var(--db-andante) var(--db-exhale) backwards; }
  :is([dir="rtl"], [dir="rtl"] *) .db-quest-word::before { transform-origin: 100% 50%; }
  .db-quest-kind { font-size: var(--db-pp); line-height: var(--db-pp-lh); font-weight: 600; letter-spacing: 0.04em; color: var(--db-graphite); }
  .db-quest[data-variant="definition"] .db-quest-sentence > .db-yours { animation-delay: calc(var(--db-andante) / 2 + var(--i, 0) * var(--db-arpeggio)); }
  .db-quest[data-variant="definition"] .db-quest-sentence { max-width: 32ch; font-size: var(--db-mp); line-height: var(--db-mp-lh); letter-spacing: var(--db-mp-tr); }
  @media (max-width: 520px) { .db-quest-word { font-size: var(--db-f); } }
  @media (forced-colors: active) { .db-quest-word { forced-color-adjust: none; color: Canvas; } .db-quest-word::before { background: CanvasText; } }

  @keyframes db-quest-turn { from { opacity: 0; translate: calc(var(--from, 1) * 8px) 0; } }
}
